<script>
const thread=document.getElementById("thread");
const messages=document.getElementById("messages");
const input=document.getElementById("input");
const composer=document.getElementById("composer");
const send=document.getElementById("send");
const historyEl=document.getElementById("history");
const sidebar=document.getElementById("sidebar");
const backdrop=document.getElementById("backdrop");
const menuButton=document.getElementById("menuButton");
const conversations=JSON.parse(localStorage.getItem("sol-chat-conversations")||"[]");
let activeId=localStorage.getItem("sol-chat-active")||null;
let busy=false;

function escapeHtml(value){
return value.replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[char]));
}

function scrollBottom(){
requestAnimationFrame(()=>messages.scrollTop=messages.scrollHeight);
}

function autosize(){
input.style.height="auto";
input.style.height=Math.min(input.scrollHeight,170)+"px";
}

function currentConversation(){
return conversations.find(item=>item.id===activeId);
}

function save(){
localStorage.setItem("sol-chat-conversations",JSON.stringify(conversations.slice(0,30)));
localStorage.setItem("sol-chat-active",activeId||"");
}

function createConversation(){
const item={id:crypto.randomUUID(),title:"Új beszélgetés",createdAt:Date.now(),messages:[]};
conversations.unshift(item);
activeId=item.id;
save();
return item;
}

function ensureConversation(){
return currentConversation()||createConversation();
}

function renderHistory(){
historyEl.innerHTML="";
conversations.forEach(item=>{
const button=document.createElement("button");
button.type="button";
button.className="history-item"+(item.id===activeId?" active":"");
button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/></svg><span>'+escapeHtml(item.title)+'</span>';
button.addEventListener("click",()=>{
if(busy)return;
activeId=item.id;
save();
renderHistory();
renderConversation();
closeSidebar();
});
historyEl.appendChild(button);
});
}

function welcome(){
thread.innerHTML=`<div class="welcome"><div class="welcome-mark">S</div><h1>Miben segíthetek?</h1><p>A gpt-5.6-sol modell Pro reasoning módban válaszol az üzeneteidre.</p><div class="suggestions"><button class="suggestion" type="button">Írj üzleti tervet</button><button class="suggestion" type="button">Magyarázz el egy fogalmat</button><button class="suggestion" type="button">Segíts kódot írni</button><button class="suggestion" type="button">Elemezz egy ötletet</button></div></div>`;
thread.querySelectorAll(".suggestion").forEach(button=>button.addEventListener("click",()=>{
input.value=button.textContent;
autosize();
input.focus();
}));
}

function createMessage(role,content,typing=false){
const item=document.createElement("article");
item.className="message "+role;
const label=document.createElement("div");
label.className="message-label";
label.textContent=role==="user"?"Te":"gpt-5.6-sol";
const bubble=document.createElement("div");
bubble.className="bubble";
if(typing){
bubble.className="typing";
bubble.innerHTML="<i></i><i></i><i></i>";
}else{
bubble.textContent=content;
}
item.append(label,bubble);
thread.appendChild(item);
scrollBottom();
return item;
}

function renderConversation(){
const conversation=currentConversation();
thread.innerHTML="";
if(!conversation||!conversation.messages.length){
welcome();
return;
}
conversation.messages.forEach(message=>createMessage(message.role,message.content));
scrollBottom();
}

function openSidebar(){
sidebar.classList.add("open");
backdrop.classList.add("open");
}

function closeSidebar(){
sidebar.classList.remove("open");
backdrop.classList.remove("open");
}

function setBusy(value){
busy=value;
send.disabled=value;
input.disabled=value;
}

async function submit(){
const content=input.value.trim();
if(!content||busy)return;
const conversation=ensureConversation();
if(!conversation.messages.length)thread.innerHTML="";
conversation.messages.push({role:"user",content});
if(conversation.title==="Új beszélgetés")conversation.title=content.replace(/\s+/g," ").slice(0,42);
save();
renderHistory();
createMessage("user",content);
input.value="";
autosize();
setBusy(true);
const pending=createMessage("assistant","",true);
try{
const response=await fetch("/api/chat",{
method:"POST",
headers:{"Content-Type":"application/json"},
body:JSON.stringify({messages:conversation.messages})
});
const data=await response.json();
if(!response.ok)throw new Error(data.detail||"Sikertelen kérés.");
const text=(data.text||"").trim();
if(!text)throw new Error("A modell nem adott vissza szöveges választ.");
conversation.messages.push({role:"assistant",content:text});
save();
pending.remove();
createMessage("assistant",text);
renderHistory();
}catch(error){
pending.remove();
const errorMessage=error instanceof Error?error.message:"Ismeretlen hiba történt.";
const item=createMessage("assistant","Hiba: "+errorMessage);
item.querySelector(".bubble").classList.add("error");
}finally{
setBusy(false);
input.focus();
}
}

document.getElementById("newChat").addEventListener("click",()=>{
if(busy)return;
createConversation();
renderHistory();
renderConversation();
closeSidebar();
input.focus();
});

document.getElementById("clearChat").addEventListener("click",()=>{
if(busy)return;
const conversation=currentConversation();
if(!conversation||!conversation.messages.length)return;
if(!confirm("Biztosan törlöd ennek a beszélgetésnek az üzeneteit?"))return;
conversation.messages=[];
conversation.title="Új beszélgetés";
save();
renderHistory();
renderConversation();
});

menuButton.addEventListener("click",openSidebar);
backdrop.addEventListener("click",closeSidebar);

composer.addEventListener("submit",event=>{
event.preventDefault();
submit();
});

input.addEventListener("input",autosize);
input.addEventListener("keydown",event=>{
if(event.key==="Enter"&&!event.shiftKey&&!event.isComposing){
event.preventDefault();
submit();
}
});

renderHistory();
renderConversation();
autosize();
</script>
