<script>
"use strict";

const STORAGE_KEY = "sol_chat_sessions_v2";
const ACTIVE_KEY = "sol_chat_active_v2";
const MAX_SESSIONS = 30;
const MAX_MESSAGES = 100;

const sidebar = document.getElementById("sidebar");
const sidebarBackdrop = document.getElementById("sidebar-backdrop");
const menuButton = document.getElementById("btn-menu");
const closeSidebarButton = document.getElementById("btn-sb-close");
const newChatButton = document.getElementById("btn-sb-new");
const clearButton = document.getElementById("btn-clear");
const historyList = document.getElementById("hlist");
const messageList = document.getElementById("msg-list");
const scrollArea = document.getElementById("scroll-area");
const textarea = document.getElementById("ta");
const sendButton = document.getElementById("sbtn");
const toastContainer = document.getElementById("toasts");

let streaming = false;
let sessions = loadSessions();
let activeSessionId = localStorage.getItem(ACTIVE_KEY) || "";
let pendingElement = null;

function loadSessions() {
try {
const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
if (!Array.isArray(parsed)) {
return [];
}
return parsed
.filter((item) => item && typeof item.id === "string" && Array.isArray(item.messages))
.slice(0, MAX_SESSIONS)
.map((item) => ({
id: item.id,
title: typeof item.title === "string" && item.title.trim() ? item.title : "Új beszélgetés",
createdAt: Number(item.createdAt) || Date.now(),
messages: item.messages
.filter((message) => message && (message.role === "user" || message.role === "assistant") && typeof message.content === "string")
.slice(-MAX_MESSAGES)
.map((message) => ({
role: message.role,
content: message.content
}))
}));
} catch (error) {
return [];
}
}

function saveSessions() {
try {
localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions.slice(0, MAX_SESSIONS)));
localStorage.setItem(ACTIVE_KEY, activeSessionId);
} catch (error) {
showToast("Nem sikerült menteni a beszélgetést.", "err");
}
}

function createSession() {
const session = {
id: crypto.randomUUID(),
title: "Új beszélgetés",
createdAt: Date.now(),
messages: []
};
sessions.unshift(session);
activeSessionId = session.id;
saveSessions();
return session;
}

function getActiveSession() {
return sessions.find((session) => session.id === activeSessionId) || null;
}

function ensureActiveSession() {
return getActiveSession() || createSession();
}

function escapeHtml(value) {
return String(value).replace(/[&<>"']/g, (character) => {
const entities = {
"&": "&amp;",
"<": "&lt;",
">": "&gt;",
'"': "&quot;",
"'": "&#039;"
};
return entities[character];
});
}

function showToast(message, type) {
const toast = document.createElement("div");
toast.className = "toast" + (type ? " " + type : "");
toast.textContent = message;
toastContainer.appendChild(toast);
window.setTimeout(() => {
toast.remove();
}, 3200);
}

function openSidebar() {
sidebar.classList.add("open");
sidebarBackdrop.classList.add("open");
sidebar.setAttribute("aria-hidden", "false");
}

function closeSidebar() {
sidebar.classList.remove("open");
sidebarBackdrop.classList.remove("open");
sidebar.setAttribute("aria-hidden", "true");
}

function formatDate(timestamp) {
const date = new Date(timestamp);
const now = new Date();
if (date.toDateString() === now.toDateString()) {
return "Ma";
}
return date.toLocaleDateString("hu-HU", {
month: "short",
day: "numeric"
});
}

function renderHistory() {
historyList.innerHTML = "";

if (!sessions.length) {
historyList.innerHTML = '<div class="hempty"><p>Még nincs mentett beszélgetés.</p></div>';
return;
}

sessions.forEach((session) => {
const card = document.createElement("button");
card.type = "button";
card.className = "hcard" + (session.id === activeSessionId ? " active" : "");
card.innerHTML = '<div class="hcard-body"><div class="hcard-pre">' + escapeHtml(session.title) + '</div><div class="hcard-meta">' + formatDate(session.createdAt) + "</div></div>";
card.addEventListener("click", () => {
if (streaming) {
return;
}
activeSessionId = session.id;
saveSessions();
renderHistory();
renderMessages();
closeSidebar();
});
historyList.appendChild(card);
});
}

function createWelcome() {
const welcome = document.createElement("div");
welcome.className = "welcome";
welcome.innerHTML = '<div class="welcome-mark">S</div><h1>Miben segíthetek?</h1><p>A gpt-5.6-sol modell Pro reasoning módban válaszol.</p><div class="suggestions"><button class="suggestion" type="button">Írj üzleti tervet</button><button class="suggestion" type="button">Segíts kódot írni</button><button class="suggestion" type="button">Magyarázz el egy fogalmat</button><button class="suggestion" type="button">Elemezz egy ötletet</button></div>';
welcome.querySelectorAll(".suggestion").forEach((button) => {
button.addEventListener("click", () => {
textarea.value = button.textContent.trim();
resizeTextarea();
updateSendButton();
textarea.focus();
});
});
return welcome;
}

function createMessageElement(role, content, isTyping) {
const group = document.createElement("article");
group.className = "msg-group " + (role === "user" ? "u" : "a");
group.setAttribute("role", "listitem");

if (role === "user") {
const bubble = document.createElement("div");
bubble.className = "bubble";
bubble.textContent = content;
group.appendChild(bubble);
return group;
}

if (isTyping) {
const typing = document.createElement("div");
typing.className = "typing";
typing.innerHTML = '<i class="td"></i><i class="td"></i><i class="td"></i>';
group.appendChild(typing);
return group;
}

const bubble = document.createElement("div");
bubble.className = "ai-bubble md";
bubble.textContent = content;
group.appendChild(bubble);
return group;
}

function renderMessages() {
messageList.innerHTML = "";
const session = getActiveSession();

if (!session || !session.messages.length) {
messageList.appendChild(createWelcome());
scrollToBottom(false);
return;
}

session.messages.forEach((message) => {
messageList.appendChild(createMessageElement(message.role, message.content, false));
});

scrollToBottom(false);
}

function scrollToBottom(smooth) {
requestAnimationFrame(() => {
scrollArea.scrollTo({
top: scrollArea.scrollHeight,
behavior: smooth ? "smooth" : "auto"
});
});
}

function resizeTextarea() {
textarea.style.height = "auto";
textarea.style.height = Math.min(textarea.scrollHeight, 160) + "px";
}

function updateSendButton() {
sendButton.disabled = streaming || !textarea.value.trim();
}

function setStreaming(value) {
streaming = value;
textarea.disabled = value;
updateSendButton();
}

function removePending() {
if (pendingElement) {
pendingElement.remove();
pendingElement = null;
}
}

function buildPayloadMessages(messages) {
return messages
.filter((message) => message && (message.role === "user" || message.role === "assistant") && typeof message.content === "string" && message.content.trim())
.slice(-MAX_MESSAGES)
.map((message) => ({
role: message.role,
content: message.content.slice(0, 50000)
}));
}

async function sendMessage() {
const content = textarea.value.trim();

if (!content || streaming) {
return;
}

const session = ensureActiveSession();

if (!session.messages.length) {
messageList.innerHTML = "";
}

session.messages.push({
role: "user",
content
});

if (session.messages.length > MAX_MESSAGES) {
session.messages = session.messages.slice(-MAX_MESSAGES);
}

if (session.title === "Új beszélgetés") {
session.title = content.replace(/\s+/g, " ").slice(0, 48) || "Új beszélgetés";
}

session.createdAt = Date.now();
sessions = sessions
.filter((item) => item.id !== session.id)
.sort((a, b) => b.createdAt - a.createdAt);
sessions.unshift(session);

saveSessions();
renderHistory();

messageList.appendChild(createMessageElement("user", content, false));

textarea.value = "";
resizeTextarea();
setStreaming(true);

pendingElement = createMessageElement("assistant", "", true);
messageList.appendChild(pendingElement);
scrollToBottom(true);

try {
const response = await fetch("/api/chat", {
method: "POST",
headers: {
"Content-Type": "application/json"
},
body: JSON.stringify({
messages: buildPayloadMessages(session.messages)
})
});

let data = null;

try {
data = await response.json();
} catch (error) {
data = null;
}

if (!response.ok) {
throw new Error(data && data.detail ? data.detail : "A szerver nem tudta feldolgozni a kérést.");
}

const text = data && typeof data.text === "string" ? data.text.trim() : "";

if (!text) {
throw new Error("A modell üres választ adott.");
}

removePending();

session.messages.push({
role: "assistant",
content: text
});

if (session.messages.length > MAX_MESSAGES) {
session.messages = session.messages.slice(-MAX_MESSAGES);
}

session.createdAt = Date.now();
saveSessions();
messageList.appendChild(createMessageElement("assistant", text, false));
renderHistory();
scrollToBottom(true);
} catch (error) {
removePending();
const message = error instanceof Error ? error.message : "Ismeretlen hiba történt.";
const errorElement = document.createElement("div");
errorElement.className = "err-bbl";
errorElement.textContent = "Hiba: " + message;
const group = document.createElement("article");
group.className = "msg-group a";
group.appendChild(errorElement);
messageList.appendChild(group);
scrollToBottom(true);
} finally {
setStreaming(false);
textarea.focus();
}
}

function clearCurrentSession() {
if (streaming) {
return;
}

const session = getActiveSession();

if (!session || !session.messages.length) {
return;
}

const confirmed = window.confirm("Biztosan törlöd az aktuális beszélgetést?");

if (!confirmed) {
return;
}

session.messages = [];
session.title = "Új beszélgetés";
session.createdAt = Date.now();
saveSessions();
renderHistory();
renderMessages();
textarea.focus();
}

textarea.addEventListener("input", () => {
resizeTextarea();
updateSendButton();
});

textarea.addEventListener("keydown", (event) => {
if (event.key === "Enter" && !event.shiftKey && !event.isComposing) {
event.preventDefault();
sendMessage();
}
});

sendButton.addEventListener("click", sendMessage);

newChatButton.addEventListener("click", () => {
if (streaming) {
return;
}
createSession();
renderHistory();
renderMessages();
closeSidebar();
textarea.focus();
});

clearButton.addEventListener("click", clearCurrentSession);
menuButton.addEventListener("click", openSidebar);
closeSidebarButton.addEventListener("click", closeSidebar);
sidebarBackdrop.addEventListener("click", closeSidebar);

if (!getActiveSession() && sessions.length) {
activeSessionId = sessions[0].id;
saveSessions();
}

renderHistory();
renderMessages();
resizeTextarea();
updateSendButton();
</script>
</body>
</html>
