import os
from pathlib import Path

import uvicorn
from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse
from openai import OpenAI
from pydantic import BaseModel, Field

BASE_DIR = Path(__file__).resolve().parent

app = FastAPI()
client = OpenAI(
    api_key=os.environ["LLMAPI_KEY"],
    base_url="",
)


class ChatRequest(BaseModel):
    messages: list[dict[str, str]] = Field(min_length=1, max_length=100)


@app.get("/")
async def index():
    return FileResponse(BASE_DIR / "index.html")


@app.post("/api/chat")
async def chat(body: ChatRequest):
    messages = []

    for message in body.messages:
        role = message.get("role", "")
        content = message.get("content", "").strip()

        if role in {"user", "assistant"} and content:
            messages.append({"role": role, "content": content[:50000]})

    if not messages or messages[-1]["role"] != "user":
        raise HTTPException(
            status_code=422,
            detail="Érvényes felhasználói üzenet szükséges.",
        )

    try:
        res = client.responses.create(
            model="gpt-5.6-sol",
            reasoning={
                "mode": "pro",
                "effort": "xhigh",
            },
            input=messages,
        )

        text = (res.output_text or "").strip()

        if not text:
            raise HTTPException(
                status_code=502,
                detail="A modell üres választ adott.",
            )

        return {"text": text}
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Modellhiba: {exc}",
        ) from exc


if __name__ == "__main__":
    uvicorn.run(
        "main:app",
        host="0.0.0.0",
        port=int(os.environ.get("PORT", "8000")),
        reload=False,
    )
